// Helper function to get service by slug
export const getServiceBySlug = (slug) => {
  return ALL_SERVICES.find((s) => s.slug === slug) || ALL_SERVICES[0];
};

// Helper function to get services by category
export const getServicesByCategory = (category) => {
  if (!category || category === "all") return ALL_SERVICES;
  return ALL_SERVICES.filter((s) => s.category === category);
};

// Featured services for homepage cards
export const FEATURED_SERVICES = ALL_SERVICES.slice(0, 6);
